    if (int.TryParse(Environment.GetEnvironmentVariable("OC_TEST_DELAY_MS"), out var waitMs) && waitMs > 0) await Task.Delay(Math.Min(waitMs, 100));
    bool transitioned = Cancellation.Transitioned(before, result);
